//! One printer over the language registry. The checked catalog supplies native node parameters.
use flow_check::{catalog::Catalog, registry::{self, Entry}};
use flow_syntax::{context, ty};
use web_export::check_cli::json_string as q;

fn arguments(entry: &Entry, catalog: &Catalog) -> Vec<(String, String, String)> {
    if let Some(op) = flow_check::op::all().iter().find(|op| op.name == entry.name) {
        let mut args = Vec::new();
        for (prefix, fields) in [("", &op.signature.pos), ("?", &op.signature.opt), (":", &op.signature.kw)] {
            args.extend(fields.iter().map(|(name, t)| (format!("{prefix}{name}"), ty::to_string(t), String::new())));
        }
        if let Some((name, t)) = &op.signature.rest { args.push((format!("{name}..."), ty::to_string(t), String::new())); }
        return args;
    }
    catalog.kinds.iter().find(|kind| kind.qualified == entry.name).map(|kind| {
        let mut args: Vec<_> = kind.slots.iter().map(|slot| (slot.name.clone(), slot.ty.as_ref().map(ty::to_string).unwrap_or_else(|| "Geometry".into()), if slot.rest { "rest".into() } else if slot.required { "required".into() } else { "optional".into() })).collect();
        args.extend(kind.parameters.iter().map(|p| (format!(":{}", p.name), p.ty.as_ref().map(flow_check::port_type::name).unwrap_or_else(|| "Text".into()), format!("{}{}", p.unit.as_ref().map(|unit| format!("unit {unit}; ")).unwrap_or_default(), p.fields.iter().map(|(_, kind, default)| format!("{kind:?}; default {default:?}")).collect::<Vec<_>>().join(", ")))));
        args
    }).unwrap_or_default()
}

pub fn print(query: Option<&str>, json: bool, all: bool) -> Result<String, String> {
    let catalog = flow_check::catalog::catalog_of_manifest(include_str!("../../flow_sop/flow_manifest.sexp")).map_err(|d| rays_diagnostic::to_string(&d))?.0;
    let entries = registry::entries(&catalog);
    let exact = query.is_some_and(|query| entries.iter().any(|e| e.name == query));
    let selected: Vec<_> = entries.iter().filter(|entry| {
        (all || !entry.hidden || exact) && query.is_none_or(|query| if exact { entry.name == query } else { entry.name.contains(query) || entry.doc.to_lowercase().contains(&query.to_lowercase()) })
    }).collect();
    if selected.is_empty() { return Err(format!("rays: doc: no names match {:?}", query.unwrap_or_default())); }
    if json {
        Ok(format!("[{}]\n", selected.iter().map(|entry| {
            let args = arguments(entry, &catalog).iter().map(|(name, t, detail)| format!("{{\"name\":{},\"type\":{},\"detail\":{}}}", q(name), q(t), q(detail))).collect::<Vec<_>>().join(",");
            format!("{{\"name\":{},\"context\":{},\"signature\":{},\"doc\":{},\"example\":{},\"hidden\":{},\"arguments\":[{}]}}", q(&entry.name), entry.context.map(|c| q(context::name(c))).unwrap_or_else(|| "null".into()), q(&entry.signature), q(&entry.doc), q(&entry.example), entry.hidden, args)
        }).collect::<Vec<_>>().join(",")))
    } else if exact {
        let entry = selected[0];
        let args = arguments(entry, &catalog).iter().map(|(name, t, detail)| format!("    {name}  {t}  {detail}\n")).collect::<String>();
        Ok(format!("{}  {}\n  {}\n  {}\n{}  example\n    {}\n", entry.name, entry.context.map(context::name).unwrap_or("form"), entry.doc, entry.signature, args, entry.example))
    } else {
        Ok(selected.iter().map(|entry| format!("{}  {}\n", entry.name, entry.doc)).collect())
    }
}

/// Compact author guide. Every function/example/name below comes from the checked registry.
pub fn guide() -> Result<String, String> {
    let catalog = flow_check::catalog::catalog_of_manifest(include_str!("../../flow_sop/flow_manifest.sexp")).map_err(|d| rays_diagnostic::to_string(&d))?.0;
    let entries = registry::entries(&catalog);
    let mut out = String::from("<!-- Generated by `rays doc --markdown`; edit registry metadata, then regenerate. -->\n# Rays Lisp\n\nA `.rays` file declares a workspace with named graphs. Graphs evaluate immutable values; the native editor projects those same forms into editable graphs.\n\n```sh\nrays doc draw/circle\nrays doc sop/\nrays check --json sketches/basic.rays\nrays render sketches/basic.rays -o basic.png --frame 30\nrays fmt sketches/basic.rays\n```\n\n`doc` accepts an exact name, namespace prefix, or search word. `--json` exposes the registry; `--all` includes internal aliases. `check --json` writes one object per diagnostic. Commands exit 0 on success, 1 for diagnostics, and 2 for a crash. Rendering uses an offscreen GPU canvas and a fixed 60 Hz clock; `--size WIDTHxHEIGHT` and `--graph NAME` select the output.\n\n## Workspace\n\n```lisp\n(workspace basic\n  (graph picture\n    (draw/circle [320 180] 42.5 :fill \"#5aaaf0\")))\n```\n\nA graph may omit `:context` when its body identifies one context. Explicit contexts remain legal. One draw graph without an editor graph opens as a canvas. `(ref name)` reads a graph; typed inputs use `(name : type)`. `let` and `let*` bind sequentially. Use `rays doc NAME` for the exact parameter types, defaults, ranges and units.\n\n## Values and coercions\n\nIntegers, floats, booleans, text, vectors, lists, arrays, records and functions are values. A keyword begins with `:`. Strings use double quotes. `;` begins a line comment.\n\n- Int widens to Float. Float does not round into Int; convert explicitly.\n- A two-coordinate vector widens to vec3 with z = 0. Draw positions use logical points.\n- A homogeneous list widens to the corresponding typed array.\n- Draw radii and line widths accept fractional values. Angles are radians.\n- Literal colours and choices are validated during checking.\n- `=`, `/`, `nth` and `count` are the public polymorphic forms.\n- Names use snake_case; axis suffixes come last, such as `divisions_x`.\n\n## Forms\n\n| Form | Meaning |\n| --- | --- |\n");
    for entry in entries.iter().filter(|e| e.context.is_none() && !e.hidden) {
        out.push_str(&format!("| `{}` | {} |\n", entry.name, entry.doc.replace('|', "\\|")));
    }
    out.push_str("\n## Namespaces\n\nEach row is a lookup target and an example from its registry entry.\n\n| Namespace | Example |\n| --- | --- |\n");
    let mut namespaces = std::collections::BTreeMap::new();
    for entry in entries.iter().filter(|e| e.context.is_some() && !e.hidden) {
        let namespace = entry.name.split_once('/').map(|(ns, _)| ns).unwrap_or("value");
        namespaces.entry(namespace).or_insert(entry);
    }
    for (namespace, entry) in namespaces { out.push_str(&format!("| `{namespace}/` | `{}` |\n", entry.example.replace('|', "\\|"))); }
    out.push_str("\nThe checked examples in `sketches/` cover larger workspaces. [Flow](../specification/flow.md) specifies language and editing contracts; [Rust crate map](../specification/api.md) explains extension ownership; [development](development.md) lists bounded checks and qualification.\n");
    Ok(out)
}
